#include <cstdio>
#include <algorithm>
#include <vector>
using namespace std;

const int INF = 0x3f3f3f3f;

int main() {
    int n, w;
    scanf("%d%d", &n, &w);
    vector<int> costs(n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &costs[i]);
    }
    vector<int> dp(w + 10, INF);
    dp[0] = 0;
    for (int total = 1; total <= w; total++) {
        for (int j = 0; j < n; j++) {
            if (total >= costs[j] && dp[total - costs[j]] != INF) {
                dp[total] = min(dp[total], dp[total - costs[j]] + 1);
            }
        }
    }
    printf("%d\n", dp[w]);
    return 0;
}
